/* THE PILL, IN ITS TWO JOBS — and the element is the difference.
 *
 * `.chip` was a Button with a toggle state; `.tag` was a copy of the same box
 * that swapped <button> for <span> and its own header said so ("sizing/colours
 * mirror .chip[secondary] so tokens and chips sit together 1:1"). They were
 * folded into one component on 2026-08-30, and the split that survives is the
 * one that was always real: a control answers hover, press and focus, a data
 * token answers nothing. So the selectors are `button.chip` and `span.chip` —
 * no flag to keep in step with the markup, and no way to give a label a
 * pressed state, which is the objection the 2026-08-26 consolidation pass
 * recorded against merging them.
 *
 * Sizing and colours are still identical to .btn, so chips, tokens and buttons
 * sit together 1:1.
 */
.chip {
  /* Sizes to its label, never to its container. `display: inline-flex` is not
     enough: as a flex or grid child with the default `stretch`, the cross size
     is set by the parent and the pill runs the full width — a badge that reads
     as a text input, which is exactly how it shipped on the patterns screen
     (measured 2026-08-22: 219px of pill around 48px of text). An explicit
     inline-size opts out of stretch, in both axes' worth of cases. */
  inline-size: fit-content;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-2);   /* icon↔label */
  /* min-block-size, not height: a fixed one is a promise the content keeps only
   * while it is short. Hand-typed data does not oblige — one tools cell in a
   * real spreadsheet is a whole comma-separated sentence, and as a fixed-height
   * pill it painted its text straight over the tags next to it. The pill grows
   * instead, and the text wraps inside it. */
  min-block-size: var(--control-height);
  padding-inline: var(--control-padding-x);
  border-radius: var(--radius-full);   /* always pill */
  border: none;
  font-family: inherit;
  font-weight: var(--control-font-weight);
  font-size: var(--control-font-size);
  /* --surface-contrast, not --secondary. --secondary IS --muted (both
   * neutral-100), so on the page surface the pill was painting itself the
   * colour of the page and there was no pill — just a word floating in a row of
   * controls that all had shapes. Same one-line rule the secondary button
   * follows: on grey go white, on white go grey. */
  background: var(--surface-contrast);
  color: var(--secondary-foreground);
}

/* ── A CONTROL: it answers the pointer and the keyboard ───── */
button.chip {
  cursor: pointer;
  transition: background var(--duration-fast), color var(--duration-fast);
}
button.chip:hover { background: var(--surface-contrast-hover); }
/* Pressed — one stop past hover. */
button.chip:active { background: var(--surface-contrast-active); }
button.chip:disabled { opacity: var(--disabled-opacity); cursor: not-allowed; pointer-events: none; }

/* ── DATA: a value, and only the X is a target ───── */
span.chip {
  padding-block: var(--space-1);
  /* A token is read as one thing, so it keeps its own words together rather
   * than letting one long name break mid-word across the row. */
  overflow-wrap: anywhere;
  max-inline-size: 100%;
}
/* THE TIGHTER END BELONGS TO THE REMOVE BUTTON, NOT TO THE TOKEN. This padding
 * was unconditional, so a token with nothing to remove — the common case in a
 * read-only row of labels — sat with 8px after its last letter and 12 before
 * its first, and read as text pushed against the right edge (owner,
 * 2026-08-29). The button brings its own visual weight; without it the pill is
 * symmetric. */
span.chip:has(.chip-remove) { padding-inline-end: var(--space-2); }

.chip-remove {
  /* 24x24. It had no size at all and took the icon's 16px, which is under the
   * SC 2.5.8 floor and sits hard against the label, so the spacing exception
   * does not rescue it either. The glyph inside is unchanged. */
  inline-size: var(--space-6);
  block-size: var(--space-6);
  flex: none;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  /* NO MARGIN OF ITS OWN: `.chip` already sets the gap between its parts, and
   * adding 4px here made it 12 — half again the space between the dot and the
   * label on every other chip in the system, so the cross read as detached from
   * the word it removes (owner, 2026-08-29). */
  border-radius: var(--radius-full);
  background: transparent;
  color: inherit;
  opacity: 0.7;
  transition: opacity var(--duration-fast), background var(--duration-fast);
}
.chip-remove:hover {
  opacity: 1;
  background: color-mix(in oklch, var(--secondary-foreground) 15%, transparent);
}
.chip-remove:active { opacity: 1; background: color-mix(in oklch, var(--secondary-foreground) 25%, transparent); }
/* The ring. It used to trade the outline for that same tint, which is a hover
 * by another name: keyboard focus and the pointer produced identical pixels,
 * and the tint measures ~1.2:1 where SC 2.4.11 asks 3:1. */
.chip-remove:focus-visible {
  opacity: 1;
  outline: var(--focus-ring);
  outline-offset: var(--ring-offset);
}

/* ── Sizes — mirror .btn ───── */
.chip[data-size="sm"] { min-block-size: var(--control-height-sm); padding-inline: var(--space-3); font-size: var(--font-sm); }
.chip[data-size="lg"] { min-block-size: var(--control-height-lg); font-size: var(--control-font-size-lg); }

/* ── Variants — identical colors to .btn ───── */
button.chip[data-variant="primary"] { background: var(--primary); color: var(--primary-foreground); }
button.chip[data-variant="primary"]:hover { background: var(--primary-hover); }
button.chip[data-variant="primary"]:active { background: var(--primary-active); }

button.chip[data-variant="ghost"] { background: transparent; color: var(--foreground); }
button.chip[data-variant="ghost"]:hover { background: var(--accent-soft); }
button.chip[data-variant="ghost"]:active { background: var(--accent); }

button.chip[data-variant="destructive"] { background: var(--destructive); color: var(--destructive-foreground); }

button.chip[data-variant="dark"] { background: var(--secondary-foreground); color: var(--background); }
button.chip[data-variant="dark"]:hover { background: var(--foreground); }

/* ── Selected — primary fill, overrides the variant (pick-one / toggle groups).
 * Placed last so it wins over variant rules at equal specificity. ───── */
button.chip[data-selected] { background: var(--primary); color: var(--primary-foreground); }
button.chip[data-selected]:hover { background: var(--primary-hover); }
button.chip[data-selected]:active { background: var(--primary-active); }

import './Chip.css'
import { type HTMLAttributes, type ReactNode, type Ref } from 'react'
import { cn } from '../lib/cn'
import { Icon, type IconName } from '../Icon'
import { Tooltip } from '../Tooltip'

/** Same variants as Button. Default is `secondary` (subtle) since chips are
 *  usually shown in groups; pass `selected` for the toggled/active state. */
type Variant = 'secondary' | 'primary' | 'ghost' | 'destructive' | 'dark'
type Size = 'sm' | 'md' | 'lg'

type Props = Omit<HTMLAttributes<HTMLElement>, 'children'> & {
  children: ReactNode
  /** Forwarded to the element this renders — the <button>, or the <span> of a
   *  data token. */
  ref?: Ref<HTMLElement>
  /** How much the chip is claiming. `secondary` (default) is a label; `primary` is the one that
   *  is selected or active; `ghost` is a chip on a busy surface; `destructive` marks something
   *  failing.
   */
  variant?: Variant
  /** Follows the row it sits in: `sm` inside a table cell or a dense toolbar, `md` on its own.
   *  Defaults to `md` as a control and `sm` as a data token, which is the size
   *  each was already shipping at. */
  size?: Size
  /** Toggled/active state for pick-one or multi-select chip groups (primary fill).
   *  A data token cannot be selected: there is nothing to press. */
  selected?: boolean
  /** Optional leading icon. */
  icon?: IconName
  /** IS THIS A CONTROL OR IS IT DATA? A control renders a <button> that answers
   *  hover, press and focus and is announced as pressed when `selected`. Data
   *  renders a <span> that does none of it: a value the reader typed or chose,
   *  which must never look pressable. Defaults to a control, and to data as
   *  soon as `onRemove` is given, because the X is then the only target. */
  interactive?: boolean
  /** Renders a trailing remove button that calls this on click. Data tokens
   *  only: a button inside a button is invalid HTML, so passing it makes the
   *  chip a token. */
  onRemove?: () => void
  /** Accessible label + tooltip for the remove button (required when removable). */
  removeLabel?: string
  disabled?: boolean
}

/**
 * The pill, in its two jobs. `interactive` (the default) is a control: a
 * Button with a toggle state, always pill-shaped — quick actions, quick
 * replies, pick-a-reason chips, filters. With `onRemove`, or with
 * `interactive={false}`, it is DATA: a static label token, the value as the
 * reader wrote or chose it, where only the trailing X does anything.
 *
 * One component because it was always one pill: <Tag> was a copy of this box
 * that swapped the element (2026-08-30). The element is the whole difference,
 * and it stays visible in the DOM — button or span — rather than being a flag
 * on a div.
 *
 * Copy: a control names the filter it applies, not the act of filtering —
 * "Overdue", not "Filter by overdue". A token is the value itself, unaltered:
 * rewording data makes it un-findable.
 */
export function Chip({
  variant = 'secondary',
  size,
  selected,
  icon,
  interactive,
  onRemove,
  removeLabel,
  disabled,
  className,
  children,
  ref,
  ...rest
}: Props) {
  const isControl = interactive ?? onRemove === undefined
  const resolvedSize = size ?? (isControl ? 'md' : 'sm')
  const glyph = icon && <Icon name={icon} />

  if (!isControl) {
    return (
      <span
        ref={ref}
        className={cn('chip', className)}
        data-variant={variant}
        data-size={resolvedSize}
        {...rest}
      >
        {glyph}
        <span className="chip-label">{children}</span>
        {onRemove && (
          <Tooltip content={removeLabel ?? ''}>
            <button type="button" className="chip-remove" aria-label={removeLabel} onClick={onRemove}>
              <Icon name="close" />
            </button>
          </Tooltip>
        )}
      </span>
    )
  }

  return (
    <button
      ref={ref as Ref<HTMLButtonElement>}
      type="button"
      className={cn('chip', className)}
      data-variant={variant}
      data-size={resolvedSize}
      data-selected={selected || undefined}
      aria-pressed={selected}
      disabled={disabled}
      {...rest}
    >
      {glyph}
      {children}
    </button>
  )
}
